script:
(function () {
  'use strict';
  // Credit self-check against editable lender rules of thumb (no credit-score prediction).
  //   monthly income          = gross annual income / 12
  //   housing ratio           = housing payment / monthly income
  //   non-housing payments    = (other debt payments + new payment) / monthly income
  //   debt-to-income ratio    = (housing + other + new payment) / monthly income
  //   credit utilization      = total revolving balances / total revolving limits
  //   room for new payments   = DTI guideline x monthly income - (housing + other + new), floored at 0
  //   Ratio checks: <= guideline -> within; DTI between guideline and stretch limit -> stretch;
  //   above -> above. History: 0 late payments / no collections / no bankruptcy or foreclosure
  //   -> clear; recent items (bankruptcy < 2 yrs, foreclosure < 3 yrs, any open collection,
  //   2+ late payments) -> flag; older items or a single late payment -> review.
  //   Inquiries <= guideline -> within. Checks with nothing to measure (no revolving limits and
  //   no balances) are shown as "Not applicable" and left out of the count.
  // Verified (scratchpad b6credit/ca.test.js): $85,000 income, $1,750 housing, $620 other ->
  //   monthly income $7,083.33, housing 24.71%, non-housing 8.75%, DTI 33.46%, room $180.00
  //   (0.36 x 7,083.33 - 2,370); $4,200 / $15,000 -> 28.00% utilization; boundary values
  //   (exactly 36% DTI = within, 43% = stretch, 43.01% = above); zero income and balances
  //   above zero limits are rejected; whole script runs under a fake DOM with no NaN.

  // ---- Calculation ----
  function ratioStatus(value, guide, stretch) {
    if (value <= guide + 1e-9) return 'within';
    if (stretch !== undefined && value <= stretch + 1e-9) return 'stretch';
    return 'above';
  }

  function assess(x) {
    var monthly = x.income / 12;
    var debts = x.housing + x.other + x.newPay;
    var nonHousing = x.other + x.newPay;
    var r = {
      monthly: monthly,
      debts: debts,
      housing: x.housing / monthly,
      consumer: nonHousing / monthly,
      dti: debts / monthly,
      util: x.limits > 0 ? x.balances / x.limits : null,
      room: Math.max(0, x.g.dti * monthly - debts),
      housingMax: x.g.housing * monthly
    };
    r.status = {
      housing: ratioStatus(r.housing, x.g.housing),
      consumer: ratioStatus(r.consumer, x.g.consumer),
      dti: ratioStatus(r.dti, x.g.dti, Math.max(x.g.dti, x.g.dtiMax)),
      util: r.util === null ? 'na' : ratioStatus(r.util, x.g.util),
      late: x.late === 0 ? 'clear' : (x.late === 1 ? 'review' : 'flag'),
      inquiries: x.inquiries <= x.g.inq ? 'within' : 'above',
      collections: x.collections === 'yes' ? 'flag' : 'clear',
      bankruptcy: x.bankruptcy === 'none' ? 'clear' : (x.bankruptcy === 'lt2' ? 'flag' : 'review'),
      foreclosure: x.foreclosure === 'none' ? 'clear' : (x.foreclosure === 'lt3' ? 'flag' : 'review')
    };
    var counted = 0, ok = 0, flags = 0;
    Object.keys(r.status).forEach(function (k) {
      var s = r.status[k];
      if (s === 'na') return;
      counted++;
      if (s === 'within' || s === 'clear') ok++;
      if (s === 'above' || s === 'flag') flags++;
    });
    r.counted = counted; r.ok = ok; r.flags = flags;
    return r;
  }

  // ---- UI ----
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var LABELS = {
    within: ['Within guideline', 'badge badge-mint'],
    clear: ['Clear', 'badge badge-mint'],
    stretch: ['Stretch', 'badge badge-butter'],
    review: ['Worth reviewing', 'badge badge-butter'],
    above: ['Above guideline', 'badge badge-blush'],
    flag: ['Likely concern', 'badge badge-blush'],
    na: ['Not applicable', 'badge badge-outline']
  };

  var BANKRUPTCY_TEXT = { none: 'None', lt2: 'Under 2 years ago', '2to4': '2 to 4 years ago', gt4: 'Over 4 years ago' };
  var FORECLOSURE_TEXT = { none: 'None', lt3: 'Under 3 years ago', '3to7': '3 to 7 years ago' };

  function num(id, blankAsZero) {
    var raw = document.getElementById(id).value.trim();
    if (raw === '' && blankAsZero) return 0;
    var v = parseFloat(raw);
    return isNaN(v) ? NaN : v;
  }
  function pct(x) { return (x * 100).toFixed(2) + '%'; }
  function pctGuide(x) { return (Math.round(x * 10000) / 100) + '%'; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addCheck(body, name, yours, guide, status, meaning) {
    var tr = document.createElement('tr');
    [name, yours, guide].forEach(function (t) {
      var td = document.createElement('td'); td.textContent = t; tr.appendChild(td);
    });
    var cell = document.createElement('td');
    var badge = document.createElement('span');
    badge.className = LABELS[status][1];
    badge.textContent = LABELS[status][0];
    cell.appendChild(badge); tr.appendChild(cell);
    var m = document.createElement('td'); m.textContent = meaning; tr.appendChild(m);
    body.appendChild(tr);
  }

  function clearResults() {
    ['caScore', 'caDti', 'caUtil', 'caRoom'].forEach(function (id) { set(id, '–'); });
    ['caScoreNote', 'caDtiNote', 'caUtilNote', 'caRoomNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('caSummary').hidden = true;
    clearBody('caChecks');
  }

  function update() {
    var x = {
      income: num('caIncome'), housing: num('caHousing', true), other: num('caOther', true), newPay: num('caNew', true),
      balances: num('caBalances', true), limits: num('caLimits', true), late: num('caLate', true), inquiries: num('caInquiries', true),
      collections: document.getElementById('caCollections').value,
      bankruptcy: document.getElementById('caBankruptcy').value,
      foreclosure: document.getElementById('caForeclosure').value,
      g: {
        housing: num('caGuideHousing') / 100, consumer: num('caGuideConsumer') / 100, dti: num('caGuideDti') / 100,
        dtiMax: num('caGuideDtiMax') / 100, util: num('caGuideUtil') / 100, inq: num('caGuideInq')
      }
    };
    var error = document.getElementById('caError');
    var amounts = [x.housing, x.other, x.newPay, x.balances, x.limits, x.late, x.inquiries];
    var guides = [x.g.housing, x.g.consumer, x.g.dti, x.g.dtiMax, x.g.util];
    var problem = '';
    if (isNaN(x.income) || x.income <= 0 || x.income > 1e9) problem = 'Enter a gross annual income above $0.';
    else if (amounts.some(function (v) { return isNaN(v) || v < 0 || v > 1e9; })) problem = 'Enter payments, balances, limits and counts of 0 or more.';
    else if (x.balances > 0 && x.limits <= 0) problem = 'Enter your total credit limits to work out utilization (or 0 balances if you have no cards).';
    else if (guides.some(function (v) { return isNaN(v) || v <= 0 || v > 1; }) || isNaN(x.g.inq) || x.g.inq < 0) problem = 'Enter guidelines from 1% to 100% and an application limit of 0 or more.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';
    x.late = Math.round(x.late); x.inquiries = Math.round(x.inquiries);

    var r = assess(x), s = r.status, g = x.g;
    set('caScore', r.ok + ' of ' + r.counted);
    set('caScoreNote', r.flags ? r.flags + (r.flags === 1 ? ' item is' : ' items are') + ' likely to concern a lender.' : 'Nothing likely to concern a lender on these checks.');
    set('caDti', pct(r.dti));
    set('caDtiNote', LABELS[s.dti][0] + ' (guideline ' + pctGuide(g.dti) + ').');
    set('caUtil', r.util === null ? 'No cards' : pct(r.util));
    set('caUtilNote', r.util === null ? 'No revolving limits entered.' : LABELS[s.util][0] + ' (guideline ' + pctGuide(g.util) + ').');
    set('caRoom', money.format(r.room) + '/mo');
    set('caRoomNote', r.room > 0 ? 'Extra monthly debt payments that keep you within the ' + pctGuide(g.dti) + ' debt-to-income guideline.' : 'Your payments already reach the debt-to-income guideline.');

    var box = document.getElementById('caSummary');
    box.hidden = false;
    var title, text;
    if (r.flags === 0 && r.ok === r.counted) {
      box.className = 'callout callout-success mt-5';
      title = 'Within every guideline';
      text = 'On these measures your application would look within the usual limits. Your credit score and the lender’s own rules still decide the outcome.';
    } else if (r.flags === 0) {
      box.className = 'callout callout-caution mt-5';
      title = 'Mostly within the guidelines';
      text = 'Nothing stands out as a likely problem, but the items marked for review or as a stretch may lead to a higher rate or extra questions.';
    } else {
      box.className = 'callout callout-warning mt-5';
      title = r.flags === 1 ? 'One item may hold you back' : r.flags + ' items may hold you back';
      text = 'Lenders are likely to look closely at the items marked as a concern. Improving them before you apply may help more than shopping for a different lender.';
    }
    set('caSummaryTitle', title);
    set('caSummaryText', text);

    var body = clearBody('caChecks');
    addCheck(body, 'Housing ratio', pct(r.housing), 'Up to ' + pctGuide(g.housing), s.housing,
      'Housing within guideline is up to ' + money.format(r.housingMax) + ' a month.');
    addCheck(body, 'Non-housing payments to income', pct(r.consumer), 'Up to ' + pctGuide(g.consumer), s.consumer,
      'Car, student, personal loan and card payments as a share of income.');
    addCheck(body, 'Debt-to-income ratio', pct(r.dti), 'Up to ' + pctGuide(g.dti) + ' (stretch ' + pctGuide(Math.max(g.dti, g.dtiMax)) + ')', s.dti,
      money.format(r.debts) + ' of debt payments on ' + money.format(r.monthly) + ' gross monthly income.');
    addCheck(body, 'Credit utilization', r.util === null ? '–' : pct(r.util), 'Up to ' + pctGuide(g.util), s.util,
      r.util === null ? 'No revolving accounts entered.' : 'Paying balances down before the statement date lowers this quickly.');
    addCheck(body, 'Late payments (2 years)', String(x.late), 'None', s.late,
      x.late ? 'Recent late payments weigh more than older ones.' : 'An on-time record is the strongest single factor.');
    addCheck(body, 'Credit applications (12 months)', String(x.inquiries), 'Up to ' + g.inq, s.inquiries,
      'Several new applications in a short time can suggest financial strain.');
    addCheck(body, 'Collections, judgments, liens', x.collections === 'yes' ? 'Yes' : 'None', 'None', s.collections,
      x.collections === 'yes' ? 'Lenders often ask for these to be paid or settled first.' : 'Nothing open.');
    addCheck(body, 'Bankruptcy', BANKRUPTCY_TEXT[x.bankruptcy] || '–', 'None', s.bankruptcy,
      x.bankruptcy === 'none' ? 'Nothing reported.' : 'Many loan programs set a waiting period after a bankruptcy; it can stay on a report for up to 10 years.');
    addCheck(body, 'Foreclosure or short sale', FORECLOSURE_TEXT[x.foreclosure] || '–', 'None', s.foreclosure,
      x.foreclosure === 'none' ? 'Nothing reported.' : 'Mortgage programs often require several years after a foreclosure; it can stay on a report for 7 years.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('caForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
